import {
    Table,
    ReferenceColumn,
    StringColumn,
    BooleanColumn,
    IntegerColumn,
    GuidColumn,
    GenericColumn,
    ListColumn,
    SystemClassNameColumn,
    FloatColumn,
    DateTimeColumn,
    UrlColumn,
    DateColumn,
    DecimalColumn,
    MultiLineTextColumn,
} from '@servicenow/sdk/core'

export const core_company = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        global_search_config_handler: 'CompanySearchConfig',
        kagami_csindex_enabled: true,
        slushbucket_omit_embedded: true,
    },
    label: 'Company',
    name: 'core_company',
    schema: {
        theme: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Theme',
            referenceTable: 'sys_ui_theme',
        }),
        name: StringColumn({
            label: 'Name',
            maxLength: 80,
        }),
        contact: ReferenceColumn({
            label: 'Contact',
            referenceTable: 'sys_user',
        }),
        primary: BooleanColumn({
            default: false,
            label: 'Primary',
        }),
        num_employees: IntegerColumn({
            label: 'Number of employees',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        phone: GenericColumn({
            columnType: 'ph_number',
            label: 'Phone',
        }),
        stock_symbol: StringColumn({
            label: 'Stock symbol',
        }),
        vendor_type: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Vendor type',
            maxLength: 1024,
            referenceTable: 'vendor_type',
        }),
        sys_class_name: SystemClassNameColumn({
            default: 'javascript:current.getTableName();',
            dropdown: 'dropdown_without_none',
            label: 'Class',
            maxLength: 80,
        }),
        zip: StringColumn({
            label: 'Zip / Postal code',
        }),
        parent: ReferenceColumn({
            label: [
                {
                    hint: 'Establishes hierarchy',
                    label: 'Parent',
                    plural: 'Companies',
                    language: 'en',
                },
            ],
            referenceTable: 'core_company',
        }),
        longitude: FloatColumn({
            label: 'Longitude',
            maxLength: 40,
        }),
        rank_tier: StringColumn({
            dropdown: 'dropdown_without_none',
            label: 'Rank tier',
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        city: StringColumn({
            label: 'City',
            maxLength: 50,
        }),
        vendor: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'We buy items from them',
                    label: 'Vendor',
                    plural: 'Vendors',
                    language: 'en',
                },
            ],
        }),
        banner_text: StringColumn({
            label: 'Banner text',
            maxLength: 4000,
        }),
        website: UrlColumn({
            label: 'Website',
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        market_cap: GenericColumn({
            attributes: {
                omit_sys_original: true,
            },
            columnType: 'currency',
            label: 'Market cap',
            maxLength: 20,
        }),
        revenue_per_year: GenericColumn({
            attributes: {
                omit_sys_original: true,
            },
            columnType: 'currency',
            label: [
                {
                    hint: 'Revenue per year (in billions)',
                    label: 'Revenue per year',
                    plural: 'Revenue per years',
                    language: 'en',
                },
            ],
            maxLength: 20,
        }),
        banner_image_light: GenericColumn({
            attributes: {
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: [
                {
                    hint: 'Should be between 20 and 40 pixels high',
                    label: 'UI16 Banner Image',
                    plural: 'UI16 Banner Images',
                    language: 'en',
                },
            ],
        }),
        fax_phone: GenericColumn({
            columnType: 'ph_number',
            label: 'Fax phone',
        }),
        stock_price: StringColumn({
            label: 'Stock price',
        }),
        fiscal_year: DateColumn({
            label: 'Fiscal year',
        }),
        country: StringColumn({
            default: 'USA',
            label: 'Country',
        }),
        notes: StringColumn({
            label: 'Notes',
            maxLength: 4000,
        }),
        lat_long_error: StringColumn({
            label: 'Lat long error',
            maxLength: 1000,
        }),
        vendor_manager: ListColumn({
            attributes: {
                slushbucket_ref_no_expand: true,
            },
            label: 'Vendor manager',
            referenceTable: 'sys_user',
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        state: StringColumn({
            label: 'State / Province',
        }),
        customer: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Is a customer of ours',
                    label: 'Customer',
                    plural: 'Customers',
                    language: 'en',
                },
            ],
        }),
        latitude: FloatColumn({
            label: 'Latitude',
            maxLength: 40,
        }),
        discount: DecimalColumn({
            label: 'Discount',
            maxLength: 15,
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
        street: MultiLineTextColumn({
            label: 'Street',
            maxLength: 255,
        }),
        manufacturer: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Makes things we buy',
                    label: 'Manufacturer',
                    plural: 'Manufacturers',
                    language: 'en',
                },
            ],
        }),
        banner_image: GenericColumn({
            columnType: 'user_image',
            label: [
                {
                    hint: 'Should be between 60 and 70 pixels high',
                    label: 'Banner image',
                    plural: 'Banner images',
                    language: 'en',
                },
            ],
        }),
        publicly_traded: BooleanColumn({
            label: 'Publicly traded',
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        coordinates_retrieved_on: DateTimeColumn({
            label: [
                {
                    hint: 'Date and time when the latitide and longitude are populated',
                    label: 'Coordinates retrieved on',
                    plural: 'Coordinates retrieved ons',
                    language: 'en',
                },
            ],
        }),
        apple_icon: GenericColumn({
            attributes: {
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: [
                {
                    hint: 'Icon for iPhone home page bookmarks which should be a 57x57 PNG file',
                    label: 'Apple icon',
                    plural: 'Apple icons',
                    language: 'en',
                },
            ],
        }),
        profits: GenericColumn({
            attributes: {
                omit_sys_original: true,
            },
            columnType: 'currency',
            label: 'Profits',
            maxLength: 20,
        }),
    },
    textIndex: true,
})
